-- =============================================================================
-- 0088_carrier_setup_package_immutability_repair.sql
-- Phase 2L.5B: freeze finalized carrier setup package artifact metadata.
--
-- 0087 already freezes package identity/snapshots and finalized package items,
-- but its package guard only freezes generated_storage_path. This replacement
-- also freezes the generated byte size, page count, and generated timestamp
-- after the one-time generating -> generated finalization transition.
-- Send summaries, void metadata, updated_at, and the existing lifecycle graph
-- remain unchanged.
-- =============================================================================

create or replace function public.guard_carrier_setup_package_immutability()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- Reservation-time identity and content snapshots are always immutable.
  if new.organization_id is distinct from old.organization_id
    or new.onboarding_application_id is distinct from old.onboarding_application_id
    or new.carrier_id is distinct from old.carrier_id
    or new.broker_id is distinct from old.broker_id
    or new.version is distinct from old.version
    or new.recipient_name is distinct from old.recipient_name
    or new.recipient_email is distinct from old.recipient_email
    or new.prepared_for_name is distinct from old.prepared_for_name
    or new.carrier_snapshot is distinct from old.carrier_snapshot
    or new.organization_snapshot is distinct from old.organization_snapshot
    or new.equipment_snapshot is distinct from old.equipment_snapshot
    or new.document_count is distinct from old.document_count
    or new.generated_by is distinct from old.generated_by
    or new.created_at is distinct from old.created_at then
    raise exception 'A setup package''s frozen identity and contents cannot be changed.';
  end if;

  -- finalize_carrier_setup_package() performs the only legitimate population
  -- of these fields while OLD.status is generating. Once the package leaves
  -- generating (generated, sent, voided, or terminal failed), every artifact
  -- descriptor is frozen, including changes to or from NULL.
  if old.status <> 'generating'
    and (
      new.generated_storage_path is distinct from old.generated_storage_path
      or new.generated_file_size_bytes is distinct from old.generated_file_size_bytes
      or new.page_count is distinct from old.page_count
      or new.generated_at is distinct from old.generated_at
    ) then
    raise exception 'A finalized setup package''s generated artifact metadata cannot be changed.';
  end if;

  -- Preserve 0087's lifecycle exactly. Send summaries, void metadata, and
  -- updated_at remain writable through their existing approved RPC paths.
  if old.status = 'generating' and new.status not in ('generated', 'failed') then
    raise exception 'Invalid setup package status transition.';
  elsif old.status = 'generated' and new.status not in ('generated', 'sent', 'voided') then
    raise exception 'Invalid setup package status transition.';
  elsif old.status = 'sent' and new.status not in ('sent', 'voided') then
    raise exception 'Invalid setup package status transition.';
  elsif old.status in ('failed', 'voided') and new.status <> old.status then
    raise exception 'Failed and voided setup packages are terminal.';
  end if;
  return new;
end;
$$;

comment on function public.guard_carrier_setup_package_immutability() is
  'Protects immutable carrier setup package identity and snapshots on every update; permits the one-time generating-to-generated artifact finalization; freezes storage path, generated byte size, page count, and generated timestamp after leaving generating; and preserves approved send, resend, void, failure, and updated_at lifecycle changes.';

